import { assetTitle, type AssetPage, type AssetSort, type AssetTypeFilter, type BrowseAsset } from '../../../components/AssetBrowsePanel'
import mockAssets from './mockAssets.json'

/** Generated by scripts/generate-mock-thumbnails.mjs. */
const ASSETS = mockAssets as BrowseAsset[]

export const PAGE_SIZE = 20

export interface AssetQuery {
  page: number
  typeFilter: AssetTypeFilter
  sort: AssetSort
}

const COMPARE: Record<AssetSort, (a: BrowseAsset, b: BrowseAsset) => number> = {
  newest: (a, b) => b.createdAt.localeCompare(a.createdAt),
  oldest: (a, b) => a.createdAt.localeCompare(b.createdAt),
  // Sorts by what the panel shows: the title, or the file name when there's no title.
  'name-asc': (a, b) => assetTitle(a).localeCompare(assetTitle(b)),
  'name-desc': (a, b) => assetTitle(b).localeCompare(assetTitle(a)),
  largest: (a, b) => b.fileSize - a.fileSize,
  smallest: (a, b) => a.fileSize - b.fileSize,
}

/** Stands in for the API: filters, sorts and pages the mock assets. */
export function mockAssetPage({ page, typeFilter, sort }: AssetQuery): AssetPage {
  const matching = ASSETS.filter((a) => typeFilter === 'ALL' || a.mediaType === typeFilter).sort(COMPARE[sort])
  const totalPages = Math.ceil(matching.length / PAGE_SIZE)
  const current = Math.min(Math.max(page, 1), Math.max(totalPages, 1))
  return {
    items: matching.slice((current - 1) * PAGE_SIZE, current * PAGE_SIZE),
    page: current,
    pageSize: PAGE_SIZE,
    totalItems: matching.length,
    totalPages,
  }
}
